// R pattern: G=1
const char* pat = "GGGGGGGGAGGAAAAGAGGGAAAAAGAAGAAG";
int n = 32;
bool match(const char* name, int* bits){
    for(int i=0;i<n;i++) if(bits[i] != (pat[i]=='G')) return false;
    printf("MATCH: %s\n", name); return true;
}
int main(){
    int bits[64];
    // mt19937_64 seed 11, various rules
    for(unsigned long long seed : {0ULL,1ULL,11ULL,42ULL}){
        { std::mt19937_64 g(seed);
          for(int i=0;i<n;i++){ double d=(g()>>11)*(1.0/9007199254740992.0); bits[i]= d<0.5; }
          char nm[64]; sprintf(nm,"mt64(%llu) d<0.5",seed); match(nm,bits);}
        { std::mt19937_64 g(seed);
          for(int i=0;i<n;i++){ unsigned long long v=g(); bits[i]= v&1; }
          char nm[64]; sprintf(nm,"mt64(%llu) v&1",seed); match(nm,bits);}
        { std::mt19937_64 g(seed);
          for(int i=0;i<n;i++){ unsigned long long v=g(); bits[i]= (v>>63)&1; }
          char nm[64]; sprintf(nm,"mt64(%llu) msb",seed); match(nm,bits);}
        { std::mt19937_64 g(seed);
          for(int i=0;i<n;i++){ unsigned long long v=g(); bits[i]= (int)(((v>>11)*(1.0/9007199254740992.0))*2); }
          char nm[64]; sprintf(nm,"mt64(%llu) int(d*2)==1",seed); match(nm,bits);}
    }
    // drand48
    for(long seed : {0L,1L,11L,42L}){
        srand48(seed);
        for(int i=0;i<n;i++){ double d=drand48(); bits[i]= d<0.5; }
