    // mt19937 32-bit
    for(unsigned seed : {0u,1u,11u,42u}){
        { std::mt19937 g(seed);
          for(int i=0;i<n;i++){ double d=(g()>>5)*(1.0/67108864.0); bits[i]= d<0.5; }
