    char out[65]; out[n]=0;
    const char* orders[] = {"ACGT","AGCT","ATCG","TCAG","ACGTN"};
    // rejection sampling: pick letter from order via (int)(d*k), accept if in "AG"
    for(unsigned long long seed=0; seed<5000; seed++){
      for(int oi=0; oi<5; oi++){
        const char* ord = orders[oi]; int k = strlen(ord);
        std::mt19937_64 g(seed);
        for(int i=0;i<n;i++){
            char c;
            for(;;){ double d=(g()>>11)*(1.0/9007199254740992.0); c=ord[(int)(d*k)]; if(c=='A'||c=='G') break; }
            out[i]=c;
        }
        char nm[80]; sprintf(nm,"mt64(%llu) rej ord=%s",seed,ord); try_match(nm,out);
      }
    }
    // non-rejection: letter = one of two alleles indexed by (int)(d*2) but TWO draws consumed per base
    for(unsigned long long seed=0; seed<5000; seed++){
        std::mt19937_64 g(seed);
        for(int i=0;i<n;i++){ g(); double d=(g()>>11)*(1.0/9007199254740992.0); out[i]= (d<0.5)?'A':'G'; }
