#include "common.h"
#include <cstdio>
#include <cstdlib>

// Resolve a 2-fold IUPAC heterozygosity code to one of its two alleles,
// chosen by drand48() (default, unseeded state). Only R/Y/S/W/K/M are
// resolved; B/D/H/V, N and everything else pass through unchanged and do
// not consume RNG draws. Case is preserved.
static char resolve_het(char c) {
    char a, b; // alleles in alphabetical order
    switch (c) {
        case 'R': case 'r': a = 'A'; b = 'G'; break;
        case 'Y': case 'y': a = 'C'; b = 'T'; break;
        case 'S': case 's': a = 'C'; b = 'G'; break;
        case 'W': case 'w': a = 'A'; b = 'T'; break;
        case 'K': case 'k': a = 'G'; b = 'T'; break;
        case 'M': case 'm': a = 'A'; b = 'C'; break;
        default: return c;
    }
    char r = drand48() < 0.5 ? b : a;
    return (c >= 'a' && c <= 'z') ? (char)(r - 'A' + 'a') : r;
}

int cmd_randbase(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: seqtk randbase <in.fa>\n");
        return 1;
    }
    SeqFile sf(argv[1]);
    if (!sf.is_open()) {
        fprintf(stderr, "[E::stk_randbase] failed to open the input file/stream.\n");
        return 1;
    }
    SeqRecord r;
    while (sf.next(r) == 1) {
        for (size_t i = 0; i < r.seq.size(); ++i)
            r.seq[i] = resolve_het(r.seq[i]);
        // Output is always FASTA, wrapped at 60; comments are dropped.
        r.comment.clear();
        print_record(stdout, r, 60, true);
    }
    return 0;
}

